def get_regime_metadata(regime_label: str, latest_year: int) -> dict:
    """Return display metadata for the selected start-regime option.

    The selected regime controls the start date only. The simulation always runs
    from that start year through the latest month in the dataset.
    """
    if regime_label == FULL_HISTORY_LABEL:
        return {"name": "Full history", "start": None, "end": latest_year, "display": f"Full history to {latest_year}"}
    meta = REGIME_LOOKUP[regime_label].copy()
    meta["display"] = f"{meta['name']} start: {meta['start']} → latest data"
    return meta


def filter_returns_by_regime_start(returns_df: pd.DataFrame, regime_label: str) -> pd.DataFrame:
    """Keep data from the selected regime's start year through the latest available month."""
    if regime_label == FULL_HISTORY_LABEL:
        return returns_df.copy().reset_index(drop=True)

    start_year = int(REGIME_LOOKUP[regime_label]["start"])
    start_date = pd.Timestamp(year=start_year, month=1, day=1)
    filtered = returns_df.loc[returns_df["date"] >= start_date].copy().reset_index(drop=True)
    if filtered.empty:
        raise ValueError(f"No return data is available from {start_year} onward for the selected regime.")
    return filtered


